def parse_csv(raw_csv: str):
    rows = []
    row = []
    field = []
    quote = None
    at_field_start = True
    i = 0
    length = len(raw_csv)

    if raw_csv.startswith("\ufeff"):
        i = 1

    while i < length:
        char = raw_csv[i]

        if quote is not None:
            if char == quote:
                if i + 1 < length and raw_csv[i + 1] == quote:
                    field.append(quote)
                    i += 2
                    continue
                quote = None
            else:
                field.append(char)
            i += 1
            continue

        if at_field_start and char in ("'", '"'):
            quote = char
            at_field_start = False
        elif char == ",":
            row.append("".join(field))
            field = []
            at_field_start = True
        elif char in ("\r", "\n"):
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            at_field_start = True
            if char == "\r" and i + 1 < length and raw_csv[i + 1] == "\n":
                i += 1
        else:
            field.append(char)
            at_field_start = False
        i += 1

    if row or field or not at_field_start:
        row.append("".join(field))
        rows.append(row)

    width = max([8] + [len(row) for row in rows])
    columns = ["column_{}".format(i + 1) for i in range(width)]
    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
